   outputDirectory=Path.GetFullPath(outputDirectory);Need(!Directory.Exists(outputDirectory)||Directory.GetFileSystemEntries(outputDirectory).Length==0,"refuse overwriting an existing capture/history directory");Directory.CreateDirectory(outputDirectory);var receipt=new Receipt{startedUtc=DateTime.UtcNow.ToString("o"),sourceRecipeSha256=Hash(recipeFile)};var saved=new Saved(loop);Exception failure=null;float deadline=Time.realtimeSinceStartup+150;IEnumerator work=null;
