  static IEnumerator CaptureAll(R23PlayableLoop loop,Recipe recipe,string output,Receipt receipt,Saved saved,float deadline,Action<string> note){
   loop.UI.OpenAppearance();foreach(var style in recipe.styles){Need(Time.realtimeSinceStartup<deadline,"150s capture bound exceeded");bool exists=false;foreach(var available in loop.Appearance.AvailableStyles)if(available.Id==style.id&&available.SourceIndex==style.sourceIndex)exists=true;Need(exists,"actual available style/sourceIndex binding: "+style.id);Need(loop.UI.BrowseAppearance(style.id),"production BrowseAppearance rejected "+style.id);float until=Mathf.Min(deadline,Time.realtimeSinceStartup+20);while((!loop.Preview.Ready||loop.Preview.Loading||loop.Preview.SelectedStyleId!=style.id)&&loop.Preview.Failure==null&&Time.realtimeSinceStartup<until)yield return null;var committed=loop.Preview.InspectPresentation();Note(note,"committed request="+style.id+" actual="+(committed==null?"null":committed.ProfileId)+" index="+(committed==null?-1:committed.SourceIndex));Need(loop.UI.CurrentViewedAppearanceId==style.id&&loop.Preview.Ready&&!loop.Preview.Loading&&loop.Preview.Failure==null&&committed!=null&&committed.ProfileId==style.id&&committed.RequestedId==style.id&&committed.SourceIndex==style.sourceIndex&&committed.HeadVisible&&committed.VisibleRenderers>0,"caption/request must match actual committed source asset/head");
    // These are the existing production preview's named, owned presentation nodes.
