=now.ProfileId,requestedId=now.RequestedId,sourceIndex=now.SourceIndex,bodyRenderers=now.VisibleRenderers,gloveRenderers=gloves.Length,headVisible=now.HeadVisible,meshNames=now.MeshNames,materialNames=now.MaterialNames,materialBindings=ReadBindings(body,gloves),lightingState=saved.MeasureLighting(avatar),materialsAndTransformsPreserved=true,localCamera=local,localTarget=target,worldCamera=camera.transform.position,worldTarget=avatar.TransformPoint(target),avatarRotation=avatar.rotation,filmicRecordings=R23GodotFilmic.RecordedPasses-before,filmicStatus=R23GodotFilmic.LastStatus??"",filmicInputQualified=R23GodotFilmic.Session.InputQualified,colorSpace=QualitySettings.activeColorSpace.ToString()};receipt.images.Add(image);Note(note,style.id+"/"+shot.name+" "+shot.classification+" camera960/FOV38 source="+(String.IsNullOrEmpty(shot.reference)?"NONE ? PROBE":shot.reference)+" Filmic="+image.filmicStatus);}
    saved.RestoreLayers();
   }
  }
  static Transform FindCommittedBody(R23AppearanceReceipt receipt,Transform avatar){Transform found=null;foreach(var node in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Exclude)){if(node.name!=receipt.RootName)continue;var head=node.Find("AvatarHead");if(head==null||!head.gameObject.activeInHierarchy||Vector3.Distance(head.position,avatar.position)>.001f)continue;Need(found==null,"ambiguous actual committed preview body");found=node;}Need(found!=null,"committed body/head does not bind actual preview frame");return found;}
  static string ReadBindings(Transform body,Renderer[] gloves){var text=new System.Text.StringBuilder();var seen=new HashSet<Material>();foreach(var r in body.GetComponentsInChildren<Renderer>(true))foreach(var m in r.sharedMaterials)if(m!=null&&seen.Add(m))text.Append(m.name).Append(" | ").Append(m.shader.name).Append(" | base=").Append(m.GetVector("_BaseColor").ToString("F6",System.Globalization.CultureInfo.InvariantCulture)).Append(" | emission=").Append(m.GetVector("_EmissionColor").ToString("F6",System.Globalization.CultureInfo.InvariantCulture)).Append(';');foreach(var r in gloves)foreach(var m in r.sharedMaterials)if(m!=null)text.Append("GLOVE:").Append(m.name).Append(" | base=").Append(m.GetVector("_BaseColor").ToString("F6",System.Globalization.CultureInfo.InvariantCulture)).Append(';');return text.ToString();}
  static void Capture(Camera camera,string path){Need(!File.Exists(path),"capture would overwrite history");var target=RenderTexture.GetTemporary(960,960,24,RenderTextureFormat.ARGB32);var previous=camera.targetTexture;var active=RenderTexture.active;Texture2D pixels=null;try{camera.targetTexture=target;camera.Render();RenderTexture.active=target;pixels=new Texture2D(960,960,TextureFormat.RGB24,false);pixels.ReadPixels(new Rect(0,0,960,960),0,0);pixels.Apply();File.WriteAllBytes(path,pixels.EncodeToPNG());}finally{camera.targetTexture=previous;RenderTexture.active=active;RenderTexture.ReleaseTemporary(target);if(pixels!=null)UnityEngine.Object.Destroy(pixels);}}
  sealed class VisualSnapshot{readonly List<Renderer> renderers=new List<Renderer>();readonly List<Matrix4x4> poses=new List<Matrix4x4>();readonly List<Material[]> materials=new List<Material[]>();readonly List<Mesh> meshes=new List<Mesh>();public VisualSnapshot(Transform root,Renderer[] gloves){renderers.AddRange(root.GetComponentsInChildren<Renderer>(true));renderers.AddRange(gloves);foreach(var r in renderers){poses.Add(r.transform.localToWorldMatrix);materials.Add(r.sharedMaterials);var f=r.GetComponent<MeshFilter>();meshes.Add(f==null?null:f.sharedMesh);}}public bool Unchanged(){for(int i=0;i<renderers.Count;i++){var r=renderers[i];if(r==null)return false;var m=r.transform.localToWorldMatrix;for(int n=0;n<16;n++)if(Mathf.Abs(m[n]-poses[i][n])>.00001f)return false;var mats=r.sharedMaterials;if(mats.Length!=materials[i].Length)return false;for(int n=0;n<mats.Length;n++)if(mats[n]!=materials[i][n])return false;var f=r.GetComponent<MeshFilter>();if((f==null?null:f.sharedMesh)!=meshes[i])return false;}return true;}}
  sealed class Saved{
